M(gaug, r"""
public static String prefill(String id, @BD@ d, int lv, int r) {
  if (id == null || d == null || !@PKG@.GearCfg.AUG_ON || @PKG@.GearCfg.AUG_PREFILL <= 0) return null;
  if (r < 0 || r >= PRER.length || !PRER[r]) return null;
  if ("craft".equals(@PKG@.GearData.str(d, "src", ""))) return null;
  if (count(d) > 0 || slots(id, d) < 1) return null;
  double x = FORCE >= 0.0 ? FORCE : @PKG@.GearRoll.RNG.nextDouble();
  if (x * 100.0 >= (double) @PKG@.GearCfg.AUG_PREFILL) { PN[1] = PN[1] + 1L; return null; }
  int w = kindAt(id, d);
  int[] ks = new int[KIND.length];
  int n = 0;
  for (int k = 0; k < KIND.length; k++) {
    if (LATER[k] || !fitsAt(k, w, id)) continue;
    ks[n] = k;
    n++;
  }
  if (n == 0) return null;
  int k = ks[PICK >= 0 ? PICK %% n : @PKG@.GearRoll.RNG.nextInt(n)];
  int t = zoneOf(lv);
  if (t > TOP[k]) t = TOP[k];
  if (t < 1) t = 1;
  @BA@ a = new @BA@();
  a.add(new org.bson.BsonString(code(k, t)));
  d.put("aug", a);
  PN[0] = PN[0] + 1L;
  return code(k, t);
}""")
